window.products.push({"id":282315,"name":"Ameriwood Home Landry Kitchen Microwave Cart, White","category":"homeandappliances","retail price":83.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/61Lo57pVUBL._AC_SL1500_.jpg","description":"Enjoy extra storage in the kitchen with the Good To Go Microwave Cart. This cart provides a place to set your microwave, as well as additional storage where you can organize kitchen essentials. Set your microwave on top of the cart and use the open storage compartment to store kitchen towels and pot holders. Concealed storage is available behind the two doors, where a shelf is available. The bottom wheels make this cart extremely mobile, allowing you to move it around the kitchen as needed. Assembly Required. Dust and wipe with a dry cloth and if needed, a damp cloth may be used sparingly.","images":["https://m.media-amazon.com/images/I/61Lo57pVUBL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Ameriwood Home","source_asin":"B07KRN1VTG","category_path":"Home & Kitchen"},"sku":"BM-282315","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07KRN1VTG","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07KRN1VTG","price_pending":true,"merchant_ready":false});
